export type AppointmentStatus = typeof AppointmentStatus[keyof typeof AppointmentStatus];


export const AppointmentStatus = {
  REQUESTED: 'REQUESTED',
  CONFIRMED: 'CONFIRMED',
  DECLINED: 'DECLINED',
  CANCELLED: 'CANCELLED',
  COMPLETED: 'COMPLETED',
} as const;

export interface AvailabilitySlot {
  id: string;
  doctor_id: string;
  doctor_name?: string;
  specialty?: string;
  starts_at: string;
  ends_at: string;
  is_open: boolean;
  is_booked: boolean;
}

export interface AvailabilityCreateRequest {
  starts_at: string;
  ends_at: string;
}

export interface Appointment {
  id: string;
  patient_id: string;
  patient_name?: string;
  doctor_id: string;
  doctor_name?: string;
  specialty?: string;
  starts_at: string;
  ends_at: string;
  status: AppointmentStatus;
  reason?: string;
  outcome_note?: string;
  resolution_reason?: string;
  /** @nullable */
  confirmed_at?: string | null;
  /** @nullable */
  completed_at?: string | null;
  created_at: string;
}

export interface AppointmentCreateRequest {
  slot_id: string;
  /** The concern in the patient's own words. Reported, not diagnostic. */
  reason?: string;
  /** Optional link to the risk analysis that prompted the booking. */
  assessment_id?: string;
}

export interface AppointmentReasonRequest {
  reason?: string;
}

export interface AppointmentCompleteRequest {
  note?: string;
}

export interface DoctorDirectoryEntry {
  id: string;
  full_name: string;
  specialty?: string;
}

export interface DoctorDirectoryList {
  count: number;
  results: DoctorDirectoryEntry[];
}

