export interface RiskRequest {
  patient_id: string;
  /** The prediction task, e.g. "cvd". */
  task: string;
}

export type RiskRequestOutcomeDetails = { [key: string]: unknown };

export interface RiskRequestOutcome {
  assessment: RiskAssessment | null;
  /** Tasks opened to chase information the analysis needed. */
  missing_data_tasks: string[];
  /** Present only on a blocked outcome. */
  status?: string;
  /** Machine-readable reason code when blocked. */
  outcome?: string;
  message?: string;
  details?: RiskRequestOutcomeDetails;
}

export interface Notification {
  id: string;
  category: string;
  subject: string;
  body: string;
  priority?: string;
  status: string;
  related_resource_type?: string;
  related_resource_id?: string;
  created_at: string;
  /** @nullable */
  read_at?: string | null;
}

export interface PaginatedNotificationList {
  count: number;
  page: number;
  page_size: number;
  num_pages: number;
  results: Notification[];
}

